import UIKit

class LocationTrackerViewController: UIViewController, UITableViewDataSource, UITableViewDelegate {

    @IBOutlet weak var locationDisplay: UILabel!
    @IBOutlet weak var locationManager: CLLocationManager!

    override func viewDidLoad() {
        super.viewDidLoad()

        locationManager.delegate = self
        locationManager.desiredAccuracy = .high
        locationManager.requestWhenInUseAuthorization()
    }

    func tableView(_ tableView: UITableView, numberOfRowsInSection section: Int) -> Int {
        return 1
    }

    func tableView(_ tableView: UITableView, cellForRowAt indexPath: IndexPath) -> UITableViewCell {
        let cell = tableView.dequeueReusableCell(withIdentifier: "LocationCell", for: indexPath)
        cell.textLabel.text = "Location: $location"
        return cell
    }

    func locationManager(_ manager: CLLocationManager) {
        if manager.isAuthorizationEnabled {
            locationManager.startUpdatingLocation()
        } else {
            locationManager.requestWhenInUseAuthorization()
        }
    }
}
```

